struct Node {
    int data;
    struct Node* next;
};

struct Node* CreateNode(int value) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->data = value;
    node->next = NULL;
    return node;
}

struct Node* MergeTwoLists(struct Node* l1, struct Node* l2) {
    // Create a dummy node to simplify pointer operations
    struct Node* dummy = CreateNode(0);
    struct Node* tail = dummy;

    while (l1 != NULL && l2 != NULL) {
        if (l1->data <= l2->data) {
            tail->next = l1;
            l1 = l1->next;
        } else {
            tail->next = l2;
            l2 = l2->next;
        }
        tail = tail->next;
    }

    // Attach the remaining nodes
    if (l1 != NULL) {
        tail->next = l1;
    } else {
        tail->next = l2;
    }

    struct Node* mergedHead = dummy->next;
    free(dummy);
    return mergedHead;
}

struct Node* MergeKLists(struct Node* lists[], int k) {
    if (k == 0) {
        return NULL;
    }
    struct Node* result = lists[0];
    for (int i = 1; i < k; i++) {
        result = MergeTwoLists(result, lists[i]);
    }
    return result;
}

```

### Example Illustration:
Let $k = 3$ sorted lists of different sizes:
- List 1: $1 \rightarrow 5 \rightarrow 7$
- List 2: $2 \rightarrow 4$
- List 3: $3 \rightarrow 8 \rightarrow 9$

**Step 1**: Merge List 1 and List 2 using `MergeTwoLists(List 1, List 2)`:
- Result = $1 \rightarrow 2 \rightarrow 4 \rightarrow 5 \rightarrow 7$

**Step 2**: Merge Result and List 3 using `MergeTwoLists(Result, List 3)`:
- Final Sorted Merged List = $1 \rightarrow 2 \rightarrow 3 \rightarrow 4 \rightarrow 5 \rightarrow 7 \rightarrow 8 \rightarrow 9$
